// ============================================================
//  NODO: Crear objeto de mapa (Proyección Geodésica en Vivo)
//  Arquitectura: Desacopla la visualización de la matemática.
//  Recibe las coordenadas del GPS crudo y calcula en tiempo 
//  real el Error Cross-Track (XTE) proyectando el punto del robot 
//  contra los segmentos rectos de la ruta ideal planificada.
// ============================================================

var rawInput = msg.payload;

try {
    // Deserialización segura
    var datos = (typeof rawInput === "string") ? JSON.parse(rawInput) : rawInput;

    // Rechazar tramas vacías o corruptas
    if (!datos.lat || !datos.lon) return null;

    var lat = parseFloat(datos.lat);
    var lon = parseFloat(datos.lon);

    // Mantenemos la memoria global sincronizada para el algoritmo A*
    global.set("robot_pos", { lat: lat, lon: lon });

    var misionActiva = flow.get("misionActiva") || false;

    // ── Salida 1: Empaquetado visual para el nodo Worldmap ──
    var msgsMap = [];

    // Trazado incondicional del vector de posición e inercia (heading)
    msgsMap.push({
        payload: {
            name:      "Robot",
            lat:       lat,
            lon:       lon,
            heading:   datos.heading,
            icon:      "car",
            iconColor: "blue",
            layer:     "Robot",
            moved:     true
        }
    });

    // ── Salida 2: Evaluación XTE en tiempo real ─────────────
    var msgXTE = null;

    if (misionActiva) {
        var track = flow.get("trackPoints") || [];
        track.push([lat, lon]);
        flow.set("trackPoints", track); // Alimentamos la memoria histórica de vuelo

        // Generamos la polilínea continua que representa la huella real (breadcrumbs)
        if (track.length >= 2) {
            msgsMap.push({
                payload: {
                    name:    "Recorrido_Real",
                    line:    track,
                    color:   "#2196F3",
                    weight:  3,
                    opacity: 0.85,
                    layer:   "Recorrido Real"
                }
            });
        }

        // Ejecución analítica de la desviación (Solo si existe un modelo de ruta cargado)
        var ruta = flow.get("rutaCalculada") || [];
        if (ruta.length >= 2) {
            var xte = calcularXTE(lat, lon, ruta); // Llamada a la proyección ortogonal
            flow.set("xte_actual", xte);

            var xteHistory = flow.get("xteHistory") || [];
            xteHistory.push(xte);
            flow.set("xteHistory", xteHistory);

            // Inyección asíncrona hacia el Dashboard UI para la barra gráfica
            msgXTE = {
                payload:  { xte_m: xte, track_pts: track.length },
                topic:    "xte"
            };
        }
    }

    // Salida 1: array de comandos para renderizado del mapa
    // Salida 2: Métrica numérica estricta para UI/Logger
    var out1 = msgsMap.length === 1 ? msgsMap[0] : msgsMap;
    return [ out1, msgXTE ];

} catch (e) {
    return null; // Prevención de caída del nodo por error léxico en el JSON
}

// ── Rutinas Matemáticas de Resolución Cruzada (Cross-Track Error) ──
function calcularXTE(lat, lon, ruta) {
    var minDist = Infinity;
    // Escaneo de fuerza bruta (Iteración sobre todos los vectores de la malla)
    for (var i = 0; i < ruta.length - 1; i++) {
        var d = distPuntoSegmento(lat, lon, ruta[i].lat, ruta[i].lon,
                                            ruta[i+1].lat, ruta[i+1].lon);
        if (d < minDist) minDist = d; // Capturar la distancia ortogonal más corta al plano más cercano
    }
    return parseFloat(minDist.toFixed(2));
}

// Transformación trigonométrica: Proyecta la Tierra esférica a un plano 2D local
// y encuentra la mínima distancia perpendicular desde un punto a un vector (A-B).
function distPuntoSegmento(pLat, pLon, aLat, aLon, bLat, bLon) {
    // Factor de compresión cosenoidal para corregir la deformación del mapa cerca de los polos
    var cosLat  = Math.cos(pLat * Math.PI / 180); 
    var mPerDeg = 111320; // Resolución aproximada ecuatorial en metros

    // Transformación a espacio Euclidiano (Metros)
    var px = (pLon - aLon) * mPerDeg * cosLat;
    var py = (pLat - aLat) * mPerDeg;
    var bx = (bLon - aLon) * mPerDeg * cosLat;
    var by = (bLat - aLat) * mPerDeg;

    // Magnitud vectorial al cuadrado del segmento
    var segLen2 = bx * bx + by * by;
    // Si los puntos del vector coinciden, retorna la distancia directa a la punta
    if (segLen2 === 0) return Math.sqrt(px * px + py * py);

    // Proyección escalar (Producto punto normalizado) forzado entre 0 y 1 (Clamp de bordes)
    var t  = Math.max(0, Math.min(1, (px * bx + py * by) / segLen2));

    // Vector residual (Diferencia ortogonal real)
    var dx = px - t * bx;
    var dy = py - t * by;

    // Hipotenusa euclidiana (Distancia final de desviación XTE)
    return Math.sqrt(dx * dx + dy * dy);
}

