// ============================================================
// UTILIDAD: MIN HEAP (Cola de Prioridad Optimizada)
// Vital para mantener la complejidad de búsqueda del A* en O(E log V)
// ============================================================
class MinHeap {
    constructor() { this.heap = []; }
    push(node) {
        this.heap.push(node);
        this._bubbleUp(this.heap.length - 1);
    }
    pop() {
        if (this.heap.length === 0) return null;
        if (this.heap.length === 1) return this.heap.pop();
        let min = this.heap[0];
        this.heap[0] = this.heap.pop();
        this._bubbleDown(0);
        return min;
    }
    _bubbleUp(index) {
        while (index > 0) {
            let parent = Math.floor((index - 1) / 2);
            if (this.heap[parent].f <= this.heap[index].f) break;
            [this.heap[parent], this.heap[index]] = [this.heap[index], this.heap[parent]];
            index = parent;
        }
    }
    _bubbleDown(index) {
        while (true) {
            let smallest = index;
            let left = 2 * index + 1;
            let right = 2 * index + 2;
            if (left < this.heap.length && this.heap[left].f < this.heap[smallest].f) smallest = left;
            if (right < this.heap.length && this.heap[right].f < this.heap[smallest].f) smallest = right;
            if (smallest === index) break;
            [this.heap[index], this.heap[smallest]] = [this.heap[smallest], this.heap[index]];
            index = smallest;
        }
    }
    get length() { return this.heap.length; }
}

// ============================================================
// RUTINAS DE EXTRACCIÓN Y LIMPIEZA DE DATOS ESPACIALES
// Sanitiza las coordenadas crudas de la base de datos Mongo
// ============================================================
function extraerCoordenadas(dato, nombre) {
    if (!dato) return null;
    if (Array.isArray(dato)) {
        if (dato.length === 0) return null;
        dato = dato[0];
    }
    let lat = dato.lat ?? dato.latitude ?? dato.latitud;
    let lon = dato.lon ?? dato.lng ?? dato.long ?? dato.longitude ?? dato.longitud;
    let latNum = parseFloat(lat);
    let lonNum = parseFloat(lon);

    // Filtro de integridad geométrica
    if (isNaN(latNum) || isNaN(lonNum)) {
        node.warn("Dato inválido en " + nombre + ": " + JSON.stringify(dato));
        return null;
    }
    if (latNum < -90 || latNum > 90 || lonNum < -180 || lonNum > 180) {
        node.warn("Coordenadas fuera de rango en " + nombre);
        return null;
    }
    return { lat: latNum, lon: lonNum };
}

function metersToDegreesLat(meters) { return meters / METERS_PER_DEGREE_LAT; }
function metersToDegreesLon(meters, latitude) {
    // Compensación de la distorsión longitudinal basada en la latitud actual
    return meters / (METERS_PER_DEGREE_LAT * Math.cos(latitude * Math.PI / 180));
}

// ============================================================
