        if (p) targets.push(p);
    });
} else {
    let p = extraerCoordenadas(targetRaw, "Objetivo Unico");
    if (p) targets.push(p);
}

if (!robotPos || targets.length === 0) {
    node.warn("⚠️ ALGORITMO DETENIDO: Faltan coordenadas válidas.");
    return null;
}

// ============================================================
// 2. GENERACIÓN DEL BOUNDING BOX DINÁMICO (Caja envolvente)
// Ajusta dinámicamente la resolución matemática del Grid para no desperdiciar RAM
// ============================================================
let lats = [robotPos.lat, ...targets.map(t => t.lat)];
let lons = [robotPos.lon, ...targets.map(t => t.lon)];

zonas.forEach(z => {
    let puntos = z.area || z.geometry?.area;
    if (Array.isArray(puntos)) {
        puntos.forEach(p => {
            let c = extraerCoordenadas(p, "ZonaCheck");
            if (c) { lats.push(c.lat); lons.push(c.lon); }
        });
    }
});

const MARGEN_EXTRA_MAPA = 0.0015; // Margen exterior de seguridad geográfico
var minLat = Math.min(...lats) - MARGEN_EXTRA_MAPA;
var maxLat = Math.max(...lats) + MARGEN_EXTRA_MAPA;
var minLon = Math.min(...lons) - MARGEN_EXTRA_MAPA;
var maxLon = Math.max(...lons) + MARGEN_EXTRA_MAPA;

const MIN_AREA = 0.0002;
if ((maxLat - minLat) < MIN_AREA) {
    const center = (maxLat + minLat) / 2;
    minLat = center - MIN_AREA / 2; maxLat = center + MIN_AREA / 2;
}
if ((maxLon - minLon) < MIN_AREA) {
    const center = (maxLon + minLon) / 2;
    minLon = center - MIN_AREA / 2; maxLon = center + MIN_AREA / 2;
}

const centerLat = (minLat + maxLat) / 2;
const MARGEN_LAT = metersToDegreesLat(MARGEN_OBSTACULO_METROS);
const MARGEN_LON = metersToDegreesLon(MARGEN_OBSTACULO_METROS, centerLat);
const latStep = (maxLat - minLat) / GRID_SIZE;
const lonStep = (maxLon - minLon) / GRID_SIZE;

// ============================================================
// FUNCIONES DE PROYECCIÓN GEOGRÁFICA <-> CARTESIANA
// ============================================================
function toGrid(lat, lon) {
    let x = Math.floor((lon - minLon) / lonStep);
    let y = Math.floor((lat - minLat) / latStep);
    return {
        x: Math.max(0, Math.min(GRID_SIZE - 1, x)),
        y: Math.max(0, Math.min(GRID_SIZE - 1, y))
    };
}
function toGeo(x, y) {
    return {
        lat: minLat + ((y + 0.5) * latStep),
        lon: minLon + ((x + 0.5) * lonStep)
    };
}

// Ray-Casting algorithm para detección geométrica de polígonos
function isPuntoInterno(puntoLat, puntoLon, poligono) {
    let inside = false;
    for (let i = 0, j = poligono.length - 1; i < poligono.length; j = i++) {
        let xi = poligono[i].lon, yi = poligono[i].lat;
        let xj = poligono[j].lon, yj = poligono[j].lat;
        let intersect = ((yi > puntoLat) !== (yj > puntoLat)) &&
            (puntoLon < (xj - xi) * (puntoLat - yi) / (yj - yi) + xi);
        if (intersect) inside = !inside;
    }
    return inside;
}

// ============================================================
// 3. ASIGNACIÓN DE MATRIZ DE COLISIONES
// ============================================================
let grid = [];
for (let i = 0; i < GRID_SIZE; i++) grid[i] = new Array(GRID_SIZE).fill(0);

// ============================================================
// 4. RASTERIZACIÓN DE OBSTÁCULOS (Zonas Tabú)
// ============================================================
let obstaculosEncontrados = 0;
zonas.forEach((zona, idx) => {
    let puntos = zona.area || zona.geometry?.area;
    if (!puntos || !Array.isArray(puntos)) return;

    let polyCoords = [], zonaLats = [], zonaLons = [];
    puntos.forEach(p => {
        let coords = extraerCoordenadas(p, "PuntoZona");
        if (coords) {
            polyCoords.push(coords);
            zonaLats.push(coords.lat);
            zonaLons.push(coords.lon);
        }
    });
    if (polyCoords.length < 3) return;

    polyCoords.forEach(p => {
        let gp = toGrid(p.lat, p.lon);
        if (grid[gp.x][gp.y] === 0) { grid[gp.x][gp.y] = 1; obstaculosEncontrados++; }
    });

    let zMinLat = Math.min(...zonaLats) - MARGEN_LAT;
    let zMaxLat = Math.max(...zonaLats) + MARGEN_LAT;
    let zMinLon = Math.min(...zonaLons) - MARGEN_LON;
    let zMaxLon = Math.max(...zonaLons) + MARGEN_LON;

    let p1 = toGrid(zMinLat, zMinLon);
    let p2 = toGrid(zMaxLat, zMaxLon);

    for (let x = p1.x; x <= p2.x; x++) {
        for (let y = p1.y; y <= p2.y; y++) {
            if (grid[x][y] === 1) continue;
            let cellGeo = toGeo(x, y);
            if (isPuntoInterno(cellGeo.lat, cellGeo.lon, polyCoords)) {
                grid[x][y] = 1;
                obstaculosEncontrados++;
            }
        }
    }
});

// ============================================================
// 5. DISTANCE TRANSFORM (Gradiente de Repulsión)
// Mapea la distancia euclidiana de cada celda libre hacia el obstáculo más cercano.
// Permite que el robot prefiera navegar por el centro de pasillos.
// ============================================================
let distanceMap = [];
for (let i = 0; i < GRID_SIZE; i++) distanceMap[i] = new Array(GRID_SIZE).fill(999);

for (let x = 0; x < GRID_SIZE; x++)
    for (let y = 0; y < GRID_SIZE; y++)
        if (grid[x][y] === 1) distanceMap[x][y] = 0;

for (let x = 0; x < GRID_SIZE; x++) {
    for (let y = 0; y < GRID_SIZE; y++) {
        if (grid[x][y] === 1) continue;
        let d = distanceMap[x][y];
        if (x > 0) {
            d = Math.min(d, distanceMap[x - 1][y] + 1);
            if (y > 0) d = Math.min(d, distanceMap[x - 1][y - 1] + 1.414);
            if (y < GRID_SIZE - 1) d = Math.min(d, distanceMap[x - 1][y + 1] + 1.414);
        }
        if (y > 0) d = Math.min(d, distanceMap[x][y - 1] + 1);
        distanceMap[x][y] = d;
    }
}
for (let x = GRID_SIZE - 1; x >= 0; x--) {
    for (let y = GRID_SIZE - 1; y >= 0; y--) {
        if (grid[x][y] === 1) continue;
        let d = distanceMap[x][y];
        if (x < GRID_SIZE - 1) {
            d = Math.min(d, distanceMap[x + 1][y] + 1);
            if (y < GRID_SIZE - 1) d = Math.min(d, distanceMap[x + 1][y + 1] + 1.414);
            if (y > 0) d = Math.min(d, distanceMap[x + 1][y - 1] + 1.414);
        }
        if (y < GRID_SIZE - 1) d = Math.min(d, distanceMap[x][y + 1] + 1);
        distanceMap[x][y] = d;
    }
}

// ============================================================
// 6. MOTOR DE BÚSQUEDA A*
// ============================================================
function findPath(start, end) {
    // Seguridad de contorno: Evitar cálculos si el inicio o fin caen dentro de un obstáculo
    if (grid[start.x][start.y] === 1) return [];
    if (grid[end.x][end.y] === 1) return [];

    let openSet = new MinHeap();
    let closedSet = new Set();
    let gScore = {};

    gScore[start.x + "," + start.y] = 0;
    openSet.push({ x: start.x, y: start.y, g: 0, f: 0, parent: null, direction: null });

    let iterations = 0;

    // Heurística Octil (Aproximación de Manhattan optimizada para matrices con diagonales)
    function heuristic(a, b) {
        let dx = Math.abs(a.x - b.x), dy = Math.abs(a.y - b.y);
        return STRAIGHT_COST * (dx + dy) + (DIAGONAL_COST - 2 * STRAIGHT_COST) * Math.min(dx, dy);
    }

    // Inyección del gradiente de repulsión al costo de la celda
    function getObstaclePenalty(x, y) {
        if (BUFFER_SEGURIDAD_CELDAS === 0) return 0;
        let dist = distanceMap[x][y];
        if (dist < BUFFER_SEGURIDAD_CELDAS)
            return NEAR_OBSTACLE_PENALTY * (BUFFER_SEGURIDAD_CELDAS - dist) / BUFFER_SEGURIDAD_CELDAS;
        return 0;
    }

    while (openSet.length > 0 && iterations++ < MAX_ITERATIONS) {
        let current = openSet.pop();

        // Condición de éxito: Llegada al nodo objetivo
        if (current.x === end.x && current.y === end.y) {
            let path = [], temp = current;
            while (temp) { path.push({ x: temp.x, y: temp.y }); temp = temp.parent; }

            totalIteracionesAStar += iterations;
            totalNodosExplorados += closedSet.size;

            return path.reverse();
        }

        closedSet.add(current.x + "," + current.y);

        // Expansión de frontera (Moore Neighborhood)
        for (let dx = -1; dx <= 1; dx++) {
            for (let dy = -1; dy <= 1; dy++) {
                if (dx === 0 && dy === 0) continue;
                let nx = current.x + dx;
                let ny = current.y + dy;
                if (nx < 0 || nx >= GRID_SIZE || ny < 0 || ny >= GRID_SIZE) continue;
                if (grid[nx][ny] === 1) continue;

                let neighborKey = nx + "," + ny;
                if (closedSet.has(neighborKey)) continue;

                // Evitar cortar esquinas (Corner-cutting protection) a través de diagonales obstruidas
                if (dx !== 0 && dy !== 0) {
                    let s1x = current.x + dx, s1y = current.y;
                    let s2x = current.x, s2y = current.y + dy;
                    if (s1x < 0 || s1x >= GRID_SIZE || s2y < 0 || s2y >= GRID_SIZE) continue;
                    if (grid[s1x][s1y] === 1 || grid[s2x][s2y] === 1) continue;
                }

                // Cálculo del Costo Total (F = G + H)
                let movementCost = (dx !== 0 && dy !== 0) ? DIAGONAL_COST : STRAIGHT_COST;
                let dirPenalty = (current.direction &&
                    (current.direction.dx !== dx || current.direction.dy !== dy))
                    ? DIRECTION_CHANGE_PENALTY : 0;
                let obsPenalty = getObstaclePenalty(nx, ny);

                let tentativeG = current.g + movementCost + dirPenalty + obsPenalty;
                let existingG = gScore[neighborKey];

                if (existingG === undefined || tentativeG < existingG) {
                    let h = heuristic({ x: nx, y: ny }, end);
                    openSet.push({
                        x: nx, y: ny,
                        g: tentativeG, h: h, f: tentativeG + h,
                        parent: current,
                        direction: { dx, dy }
                    });
                    gScore[neighborKey] = tentativeG;
                }
            }
        }
    }

    // Abortado por timeout de seguridad computacional
    totalIteracionesAStar += iterations;
    totalNodosExplorados += closedSet.size;

    return [];
}

// ============================================================
// 7. FILTRO DE SIMPLIFICACIÓN DE TRAYECTORIA (String Pulling / Line of Sight)
// Comprime drásticamente la matriz densa del A* a un vector minimalista
// reduciendo el tráfico de datos en la red LoRa (Low Power WAN).
// ============================================================
function hasLineOfSight(from, to) {
    // Algoritmo de Bresenham adaptado para colisiones de rasterizado
    let x0 = from.x, y0 = from.y, x1 = to.x, y1 = to.y;
    let dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0);
    let sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1;
    let err = dx - dy;

    while (true) {
        if (x0 < 0 || x0 >= GRID_SIZE || y0 < 0 || y0 >= GRID_SIZE) return false;
        if (grid[x0][y0] === 1) return false;
        if (BUFFER_SEGURIDAD_CELDAS > 1 && distanceMap[x0][y0] < 1) return false;
        if (x0 === x1 && y0 === y1) break;

        let e2 = 2 * err, stepX = false, stepY = false;
        if (e2 > -dy) { err -= dy; x0 += sx; stepX = true; }
        if (e2 < dx) { err += dx; y0 += sy; stepY = true; }

        if (stepX && stepY) {
            let side1x = x0 - sx, side1y = y0, side2x = x0, side2y = y0 - sy;
            if (side1x >= 0 && side1x < GRID_SIZE && side2y >= 0 && side2y < GRID_SIZE) {
                if (grid[side1x][side1y] === 1 || grid[side2x][side2y] === 1) return false;
            }
        }
    }
    return true;
}

function simplifyPath(path) {
    if (path.length <= 2) return path;
    let simplified = [path[0]], currentIdx = 0;
    while (currentIdx < path.length - 1) {
        let farthestVisible = currentIdx + 1;
        // Búsqueda voraz (Greedy) del nodo visible más lejano
        for (let i = path.length - 1; i > currentIdx; i--) {
            if (hasLineOfSight(path[currentIdx], path[i])) {
                farthestVisible = i; break;
            }
        }
        simplified.push(path[farthestVisible]);
        currentIdx = farthestVisible;
    }
    return simplified;
}

// BUCLE DE GENERACIÓN DE RUTAS (Procesamiento en Serie para múltiples nodos)
let fullGeoPath = [];
let currentGeoStart = { lat: robotPos.lat, lon: robotPos.lon };
let rutasCalculadas = 0;
let totalPuntosAStarCrudos = 0;

for (let i = 0; i < targets.length; i++) {
    let currentGeoEnd = { lat: targets[i].lat, lon: targets[i].lon };

    let startGrid = toGrid(currentGeoStart.lat, currentGeoStart.lon);
    let endGrid = toGrid(currentGeoEnd.lat, currentGeoEnd.lon);

    let segmentPath = findPath(startGrid, endGrid);

    if (segmentPath.length === 0) break;

    totalPuntosAStarCrudos += segmentPath.length;
    let simplifiedSegment = simplifyPath(segmentPath); // Compresión de datos

    let geoSegment = simplifiedSegment.map(p => toGeo(p.x, p.y));
    geoSegment[0] = currentGeoStart;
    geoSegment[geoSegment.length - 1] = currentGeoEnd;

    // Fusión de segmentos eliminando duplicidades en las costuras
    if (fullGeoPath.length > 0) geoSegment.shift();

    fullGeoPath = fullGeoPath.concat(geoSegment);
    currentGeoStart = currentGeoEnd;
    rutasCalculadas++;
}

if (fullGeoPath.length === 0) {
    node.warn("⚠️ No se generó ninguna ruta válida.");
    return null;
}

let geoPath = fullGeoPath;

// ============================================================
// 11. CÁLCULO DE MÉTRICAS Y DESPACHO (Dashboard/MongoDB)
// ============================================================
flow.set("rutaCalculada", geoPath);

// --- CÁLCULO DE DISTANCIA ORTODRÓMICA ---
let totalDistance = 0;
for (let i = 1; i < geoPath.length; i++) {
    let p1 = geoPath[i - 1], p2 = geoPath[i];
    let dLat = (p2.lat - p1.lat) * METERS_PER_DEGREE_LAT;
    let dLon = (p2.lon - p1.lon) * METERS_PER_DEGREE_LAT * Math.cos(p1.lat * Math.PI / 180);
    totalDistance += Math.sqrt(dLat * dLat + dLon * dLon);
}

// --- CIERRE DE BENCHMARK ---
const endTime = Date.now();
const executionTimeMs = (endTime - startTime).toFixed(0);

// --- SALIDA 1: COMANDOS VISUALES PARA EL WORLDMAP ---
var linePoints = geoPath.map(p => [p.lat, p.lon]);
var msgRobot = {
    payload: {
        name: "Ruta_Calculada",
        line: linePoints,
        color: "#00FF00",
        weight: 4,
        layer: "Ruta"
    }
};

// --- SALIDA 2: EMPAQUETADO DE MÉTRICAS ANALÍTICAS ---
// Calcula la eficiencia del filtro de compresión espacial (String Pulling)
let compresionPath = totalPuntosAStarCrudos > 0 
    ? (100 - (geoPath.length / totalPuntosAStarCrudos * 100)).toFixed(1) 
    : 0;

let textoMétricas = '<br/><br/>' +
    `⏱️ Tiempo de ejecución: ${executionTimeMs} ms<br/>` +
    `🔄 Iteraciones A*: ${totalIteracionesAStar}<br/>` +
    `🔍 Nodos explorados: ${totalNodosExplorados}<br/>` +
    `📏 Distancia total: ${Math.round(totalDistance)} m<br/>` +
    `🔢 Puntos crudos (A*): ${totalPuntosAStarCrudos}<br/>` +
    `📉 Puntos finales (LoRa): ${geoPath.length}<br/>` +
    `🗜️ Reducción de carga: ${compresionPath}%<br/>` +
    `🎯 Metas logradas: ${rutasCalculadas} de ${targets.length}<br/>` +
    `🧱 Zonas tabú leídas: ${obstaculosEncontrados}`;

var msgDashboard = { payload: textoMétricas };

node.status({
    fill: "green", shape: "dot",
    text: `${geoPath.length} pts | ~${Math.round(totalDistance)}m | ${executionTimeMs}ms`
});

return [msgRobot, msgDashboard];

msg.payload = {
    "command": { "showlayer": "drawing" }
};

return msg;

// ============================================================
//  NODO: wpt (Controlador de Transmisión LoRa y Flow Control)
//  Arquitectura: Implementa un protocolo rudimentario ARQ (Automatic 
//  Repeat reQuest) y controla la cadencia de la cola FIFO para no
//  saturar la ventana de recepción del microcontrolador Edge (STM32).
// ============================================================
const BATCH_SIZE     = 5;  // Puntos empaquetados por trama para optimizar el Air Time
const QUEUE_CAPACITY = 30; // Profundidad máxima del buffer RTOS reportada por el nodo Edge

var raw = typeof msg.payload === "string" ? msg.payload.trim() : "";

// ============================================================
// 1. INYECCIÓN DEL PLAN DE VUELO (Evento Botón Dashboard)
// ============================================================
var isButton = (raw === "START_OTA");

if (isButton) {
    var ruta = flow.get("rutaCalculada");
    if (!ruta || ruta.length === 0) {
        node.warn("❌ No hay ruta calculada para enviar.");
        return null;
    }

    if (flow.get("transmitiendo")) {
        node.warn("⚠️ Desbloqueando transmisión anterior...");
    }

    var msgsComandos = [];
    var msgsMapa     = [];
    var bufferPuntos = [];
    var totalPuntos  = 0;

    // Comando destructor inicial para limpiar la RAM del RTOS remoto
    msgsComandos.push("CMD:RESET");

    // Serialización del vector de coordenadas a formato CSV ligero
    for (var i = 1; i < ruta.length; i++) {
        var pt = ruta[i];
        // Truncado a 6 decimales para mantener resolución submétrica minimizando bytes
        bufferPuntos.push(pt.lat.toFixed(6) + "," + pt.lon.toFixed(6));
        totalPuntos++;

        // Marcadores visuales de control
        msgsMapa.push({
            payload: {
                name: "Punto_" + i, lat: pt.lat, lon: pt.lon,
                layer: "Puntos Carga", icon: "dot-circle-o",
                iconColor: "orange", label: "P" + i, clickable: true
            }
        });

        // Fragmentación del payload (Batching) al alcanzar el límite definido
        if (bufferPuntos.length === BATCH_SIZE || i === ruta.length - 1) {
            msgsComandos.push("WPT:" + bufferPuntos.join(";"));
            bufferPuntos = [];
        }
    }
    // Comando verificador de integridad de memoria
    msgsComandos.push("CMD:CHECK");

    // Registro de estado de la transacción en memoria del Node-RED
    flow.set("totalPuntosEnviados", totalPuntos);
    flow.set("puntosEnRobot",       0);
    flow.set("lastBatch",           []);
    flow.set("transmitiendo",       true);

    var primerCmd = msgsComandos.shift();
    flow.set("cmdQueue", msgsComandos);

    node.warn("🚀 BOTÓN PRESIONADO. Puntos: " + totalPuntos);
    node.warn("➡️ ENVIANDO: " + primerCmd);

    return [ [{ payload: primerCmd }], msgsMapa ];
}

// ============================================================
// 2. MÁQUINA DE ESTADOS ASÍNCRONA (Respuesta desde Nodo Edge)
// ============================================================
else {

    // Descarte temprano (Filtro anti-ruido serial)
    if (raw === "CMD:START" || raw === "CMD:STOP" || raw === "CMD:RESET" ||
        raw === "CMD:CHECK" || raw === "CMD:EVASION_ON" || raw === "CMD:EVASION_OFF" ||
        raw === "F" || raw === "B" || raw === "L" || raw === "R" || raw === "S") {
        return null;
    }

    // Bypass de telemetría de consola (Logs de sistema del Gateway ESP32)
    if (raw.startsWith("{\"log\"") || raw.startsWith("{\"error\"")) {
        node.warn("📡 ESP32 INFO: " + raw);
        return null;
    }

    if (raw === "" || raw.startsWith("{\"lat\"")) return null;

    // --- A. GATILLO DE TRANSICIÓN: ESP32 BASE READY ---
    // El Gateway local confirma que el aire está limpio para transmitir el siguiente lote
    if (raw === "BASEREADY") {
        if (!flow.get("transmitiendo")) return null;

        var queue = flow.get("cmdQueue") || [];
        if (queue.length === 0) {
            node.warn("✅ TRANSMISIÓN FINALIZADA CON ÉXITO.");
            flow.set("transmitiendo", false);
            return null;
        }

        var nextCmd = queue.shift();
        flow.set("cmdQueue", queue);

        // Guardamos el lote actual en caché. Si el robot no responde con WPT_OK, 
        // usaremos este caché para el reintento (ARQ Retransmission).
        if (nextCmd.startsWith("WPT:")) {
            flow.set("lastBatch", nextCmd.substring(4).split(";"));
        }

        node.warn("➡️ ENVIANDO: " + nextCmd + " (Faltan " + queue.length + " lotes)");
        return [{ payload: nextCmd }, null];
    }

    // --- B. ACUSE DE RECIBO DE LOTE (ACK ESPACIAL) ---
    // El robot confirma cuántos puntos procesó y cuánta RAM le queda
    if (raw.startsWith("MSG:WPT_OK_")) {
        node.warn("📥 " + raw);
        var lastBatch    = flow.get("lastBatch") || [];
        var expected     = lastBatch.length;
        var received     = 0;
        var espacioLibre = QUEUE_CAPACITY;

        // Decodificación mediante RegEx del payload devuelto
        var extMatch = raw.match(/^MSG:WPT_OK_(\d+)_FREE_(\d+)$/);
        if (extMatch) {
            received     = parseInt(extMatch[1], 10);
            espacioLibre = parseInt(extMatch[2], 10);
        } else {
            received = parseInt(raw.substring(11), 10); // Modo legado (Fallback)
        }

        var enRobot = (flow.get("puntosEnRobot") || 0) + received;
        flow.set("puntosEnRobot", enRobot);

        // --- MANEJO DE INTEGRIDAD Y REENTREGA ---
        // Si el robot reportó procesar menos puntos de los que enviamos (Buffer Overrun en destino)
        if (received < expected) {
            var missing = lastBatch.slice(received);
            node.warn("⚠️ LOTE INCOMPLETO. Reencolando " + missing.length + " pts...");

            // Adaptación de Congestión: Reducimos el tamaño del lote al espacio físico reportado
            var efectivoBatch = (espacioLibre > 0) ? Math.min(BATCH_SIZE, espacioLibre) : BATCH_SIZE;
            var lotesFaltantes = [];
            for (var i = 0; i < missing.length; i += efectivoBatch) {
                lotesFaltantes.push("WPT:" + missing.slice(i, i + efectivoBatch).join(";"));
            }
            // Inyectamos los lotes faltantes al frente de la cola (Pre-pend)
            var currentQueue = flow.get("cmdQueue") || [];
            flow.set("cmdQueue", lotesFaltantes.concat(currentQueue));
        }
        flow.set("lastBatch", []); // Limpieza de caché de reintento
        return null;
    }

    // --- C. CONFIRMACIÓN FINAL DE INTEGRIDAD (Checksum Funcional) ---
    if (raw.startsWith("MSG:COUNT=")) {
        node.warn("📥 " + raw);
        flow.set("transmitiendo", false);
        flow.set("cmdQueue", []); // Cerrar la transacción de forma segura
        return null;
    }

    // --- D. ACUSE DE RESET INICIAL ---
    if (raw.startsWith("MSG:RESET_OK")) {
        node.warn("📥 " + raw);
        return null; 
    }

    return null;
}

// ============================================================
//  NODO: Retorno de comandos v5
//  Salida 1 → ui_text "Robot" + Control Misión (para fin natural)
//  Salida 2 → ui_template "LoRa métricas" + MongoDB arq_metrics
//  Salida 3 → worldmap
// ============================================================

var rawInput = typeof msg.payload === 'string'
    ? msg.payload
    : JSON.stringify(msg.payload);

var statusMsg  = "";
var metricsMsg = null;

// Leer contadores acumulados desde flow (persisten entre mensajes)
var loraRetries  = flow.get("loraRetries")  || 0;
var loraDropped  = flow.get("loraDropped")  || 0;

// ── 1. PARSEO JSON (ESP32 base) ─────────────────────────────────
try {
    var jsonObj = JSON.parse(rawInput);

    if (jsonObj.rssi !== undefined) {
        flow.set("last_rssi", jsonObj.rssi);
    }
    if (jsonObj.log && jsonObj.log.includes("TIMEOUT")) {
        loraRetries++;
        flow.set("loraRetries", loraRetries);
        statusMsg = "⚠️ Retry detected (" + loraRetries + " total).";
    }
    if (jsonObj.error && jsonObj.error.includes("DROPPED")) {
        loraDropped++;
        flow.set("loraDropped", loraDropped);
        statusMsg = "❌ Packet dropped. Total: " + loraDropped;
    }
} catch(e) {}

// ── 2. PARSEO STRINGS (robot STM32) ─────────────────────────────

// A. RESET OK — inicio de carga de waypoints
// Se guarda el timestamp AHORA para calcular latencia OTA después.
if (rawInput.includes("MSG:RESET_OK")) {
    flow.set("otaStartTime", Date.now()); // timestamp preciso del inicio OTA
    flow.set("loraRetries", 0);
    flow.set("loraDropped", 0);
    statusMsg = "🗑️ Memory cleared. Transmitting route (OTA)...";
}

// B. LOTE OK
else if (rawInput.includes("MSG:WPT_OK_")) {
    var match = rawInput.match(/WPT_OK_(\d+)_FREE_(\d+)/);
    if (match) {
        statusMsg = "✅ Batch saved: " + match[1] + " pts (Free: " + match[2] + ").";
    } else {
        var ms = rawInput.match(/WPT_OK_(\d+)/);
        if (ms) statusMsg = "✅ Batch saved: " + ms[1] + " pts.";
    }
}

// C. COUNT → fin real de la transferencia OTA
else if (rawInput.includes("MSG:COUNT=")) {
    var countMatch = rawInput.match(/COUNT=(\d+)/);
    if (countMatch) {
        var puntosRobot     = parseInt(countMatch[1]);
        var rutaOriginal    = flow.get("rutaCalculada") || [];
        var puntosEsperados = rutaOriginal.length > 1 ? (rutaOriginal.length - 1) : 0;
        var pdr = puntosEsperados > 0
            ? parseFloat(((puntosRobot / puntosEsperados) * 100).toFixed(1))
            : 0;
        flow.set("last_pdr", pdr);

        // calcular latencia OTA 
        var otaEnd     = Date.now();
        var otaStart   = flow.get("otaStartTime") || 0;
        var otaLatency = otaStart > 0
            ? parseFloat(((otaEnd - otaStart) / 1000).toFixed(2))
            : 0;
        flow.set("last_ota_latency", otaLatency);

        statusMsg = "📊 OTA complete. " + puntosRobot + " pts in robot";
        if (puntosEsperados > 0) statusMsg += " (PDR: " + pdr + "%)";
        statusMsg += ". OTA latency: " + otaLatency + "s";
        metricsMsg = null;
    }
}

// D. NAV STARTED → solo guarda el tiempo de inicio de misión
else if (rawInput.includes("MSG:NAV_STARTED")) {
    flow.set("navStartTime", Date.now());
    flow.set("navStopTime",  null);   // ← resetear el stop del ciclo anterior
    statusMsg = "🚀 Navigation STARTED.";
    metricsMsg = null;
}

// E. STOPPED → armar registro ARQ completo para MongoDB y template
else if (rawInput.includes("MSG:STOPPED")) {
    var stopTime    = Date.now();
    flow.set("navStopTime", stopTime); 
    var navStart2   = flow.get("navStartTime") || 0;
    var missionTime = navStart2 > 0
        ? parseFloat(((stopTime - navStart2) / 1000).toFixed(2))
        : 0;

    var arqRecord = {
        timestamp:         new Date().toISOString(),
        prueba:            "P" + (flow.get("prueba_counter") || 1),
        distancia_aprox_m: null,  // rellenar manualmente
        rssi_dbm:          flow.get("last_rssi")        || 0,
        reintentos_arq:    flow.get("loraRetries")      || 0,
        paquetes_dropped:  flow.get("loraDropped")      || 0,
        pdr_pct:           flow.get("last_pdr")         || 0,
        latencia_ota_s:    flow.get("last_ota_latency") || 0,
        duracion_mision_s: missionTime
    };

    flow.set("prueba_counter", (flow.get("prueba_counter") || 1) + 1);
    flow.set("last_arq_record", arqRecord);

    statusMsg = "🛑 Robot stopped. Duration: " + missionTime + "s";
    metricsMsg = { payload: [arqRecord], topic: "arq_fin" };
}

// F. SIN PUNTOS
else if (rawInput.includes("ERR:NO_POINTS")) {
    statusMsg = "⚠️ Error: Robot tried to start without waypoints.";
}

// G/H. EVASIÓN
else if (rawInput.includes("MSG:EVASION_ON")) {
    flow.set("evasionActiva", true);
    statusMsg = "🛡️ Local evasion ENABLED.";
}
else if (rawInput.includes("MSG:EVASION_OFF")) {
    flow.set("evasionActiva", false);
    statusMsg = "⛔ Local evasion DISABLED.";
}

// Procesar ACK parámetros
else if (rawInput.startsWith("ACK:GPSF_")) {
    statusMsg = "✓ Filtro GPS cambiado a G" + rawInput.charAt(9);
}
else if (rawInput === "ACK:KP")     {  statusMsg = "✓ KP aplicado"; }
else if (rawInput === "ACK:KD")     {  statusMsg = "✓ KD aplicado"; }
else if (rawInput === "ACK:XTEKP")  { statusMsg = "✓ XTE KP aplicado"; }
else if (rawInput === "ACK:XTEMAX") { statusMsg= "✓ XTE MAX aplicado";  }
else if (rawInput.startsWith("ACK:DECL")) { statusMsg = "✓ Declinación magnética actualizada"; }

// I. WAYPOINT ALCANZADO
else if (rawInput.startsWith("MSG:WPT_REACHED_")) {
    var wpNum = rawInput.replace("MSG:WPT_REACHED_", "");
    statusMsg = "📍 Waypoint " + wpNum + " reached.";
}

