// FUNCIÓN DE CONSOLIDACIÓN ANALÍTICA (Métricas de Fidelidad)
// ─────────────────────────────────────────────────────────────
function buildMisionRecord(abortada) {
    // Extracción de memoria de la serie de tiempo XTE almacenada
    var xteHistory = flow.get("xteHistory") || [];
    var trackPts   = flow.get("trackPoints") || [];
    var estado     = abortada ? "ABORTADA" : "COMPLETADA";

    var misionNum = flow.get("mision_counter") || 1;
    flow.set("mision_counter", misionNum + 1);

    // Estructura base del Documento BSON para MongoDB
    var base = {
        timestamp:      new Date().toISOString(),
        mision:         "M" + misionNum,
        wpt_enviados:   flow.get("mision_wpt_enviados") || 0,
        obstaculos_din: flow.get("evasionActiva")       || false, // Disparo de lógica difusa
        duracion_s:     calcDuracion(),
        estado:         estado,
        puntos_track:   trackPts.length,
        evento:         "FIN_MISION"
    };

    if (xteHistory.length === 0) {
        // Prevención de división por cero
        return Object.assign(base, {
            xte_promedio_m: null,
            xte_maximo_m:   null,
            xte_rms_m:      null,
            fidelidad_pct:  null,
            nota:           "No telemetry data during mission"
        });
    }

    // Cálculo matemático de dispersión (Desviación vs Ruta Ideal)
    var suma = 0, sumaC2 = 0, maximo = 0;
    for (var i = 0; i < xteHistory.length; i++) {
        var v = xteHistory[i];
        suma   += v;
        sumaC2 += v * v; // Sumatoria de cuadrados para el RMS
        if (v > maximo) maximo = v; // Peak Detector
    }

    var promedio  = suma / xteHistory.length;
    var rms       = Math.sqrt(sumaC2 / xteHistory.length); // Raíz Cuadrada Media

    // Tasa de éxito direccional (Porcentaje del tiempo que operó dentro de 1 metro de tolerancia)
    var UMBRAL_M  = 1.0;
    var dentro    = xteHistory.filter(function(v) { return v <= UMBRAL_M; }).length;
    var fidelidad = parseFloat(((dentro / xteHistory.length) * 100).toFixed(1));

    return Object.assign(base, {
        xte_promedio_m: parseFloat(promedio.toFixed(2)),
        xte_maximo_m:   parseFloat(maximo.toFixed(2)),
        xte_rms_m:      parseFloat(rms.toFixed(2)),
        fidelidad_pct:  fidelidad,
        umbral_m:       UMBRAL_M
    });
}

